public class LoggingBuffer {
    private static final Logger LOG = Logger.getLogger(LoggingBuffer.class);
    private LoggingEvent[] buffer;
    private int head;
    private int tail;
    private int size;

    public LoggingBuffer(int capacity) {
        buffer = new LoggingEvent[capacity];
        head = 0;
        tail = 0;
        size = 0;
    }

    public void put(LoggingEvent o) {
        if (size == buffer.length) {
            LOG.warn("Buffer is full, event silently dropped: " + o);
            return;
        }
        buffer[tail] = o;
        tail = (tail + 1) % buffer.length;
        size++;
    }
}

