import java.net.URI;
import java.util.List;

public class URIUtils {

    /** 
     * Decode the path component of a URI as path segments.
     * @param u the URI. If the path component is an absolute path componentthen the leading '/' is ignored and is not considered a delimiator of a path segment.
     * @param decode true if the path segments of the path componentshould be in decoded form.
     * @return the list of path segments.
     */
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        String path = u.getPath();
        if (path == null || path.isEmpty()) {
            return List.of();
        }

        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        String[] segments = path.split("/");
        List<PathSegmentImpl> decodedSegments = List.of();

        for (String segment : segments) {
            if (decode) {
                segment = java.net.URLDecoder.decode(segment, "UTF-8");
            }
            decodedSegments.add(new PathSegmentImpl(segment));
        }

        return decodedSegments;
    }

    // Assuming PathSegmentImpl is a class that represents a path segment
    static class PathSegmentImpl {
        private String segment;

        public PathSegmentImpl(String segment) {
            this.segment = segment;
        }

        public String getSegment() {
            return segment;
        }
    }
}

