public class GraphPathTransformer {

    protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("Tour and graph cannot be null");
        }

        SimpleGraph<V, E> pathGraph = new SimpleGraph<>(graph.getEdgeFactory());

        for (E edge : tour) {
            pathGraph.addEdge(edge);
        }

        return new GraphPath<>(pathGraph, pathGraph.vertexSet().iterator().next(), pathGraph.vertexSet().iterator().next());
    }
}

