import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class StringUnescape {

    /** 
     * Unescape a string DOT identifier.
     * @param input the input
     * @return the unescaped output
     */
    private String unescapeId(String input) {
        if (input == null) {
            return null;
        }

        // Regular expression to match escaped characters
        Pattern pattern = Pattern.compile("\\\\([0-7]{3}|x[0-9a-fA-F]{2})");
        Matcher matcher = pattern.matcher(input);

        StringBuffer sb = new StringBuffer();

        while (matcher.find()) {
            String escaped = matcher.group(1);
            if (escaped.startsWith("x")) {
                // Hexadecimal escape
                int value = Integer.parseInt(escaped.substring(1), 16);
                matcher.appendReplacement(sb, String.valueOf((char) value));
            } else {
                // Octal escape
                int value = Integer.parseInt(escaped, 8);
                matcher.appendReplacement(sb, String.valueOf((char) value));
            }
        }

        matcher.appendTail(sb);

        return sb.toString();
    }

    public static void main(String[] args) {
        StringUnescape unescape = new StringUnescape();
        String input = "Hello\\x41\\x6c\\x6c\\x6f";
        String output = unescape.unescapeId(input);
        System.out.println(output);  // Output: HelloAlllo
    }
}

