import java.util.List;
import java.util.Set;

public class GraphProcessor {

    private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        // Move all vertices from the bucket with label minLabel to the bucket with label 0
        Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
        Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);

        if (minLabelBucket != null && !minLabelBucket.isEmpty()) {
            zeroLabelBucket.addAll(minLabelBucket);
            minLabelBucket.clear();
        }

        // Update the labeling accordingly
        for (int label : labels) {
            if (label == minLabel) {
                label = 0;
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        List<Set<Integer>> bucketsByLabel = List.of(
            Set.of(1, 2, 3),
            Set.of(4, 5),
            Set.of(6, 7, 8, 9)
        );
        List<Integer> labels = List.of(1, 2, 3, 4, 5, 6, 7, 8, 9);
        int minLabel = 1;

        GraphProcessor processor = new GraphProcessor();
        processor.reload(bucketsByLabel, labels, minLabel);

        // Print the updated buckets
        for (int i = 0; i < bucketsByLabel.size(); i++) {
            System.out.println("Bucket " + i + ": " + bucketsByLabel.get(i));
        }
    }
}

