    while (!foundTerminator) {
        int read = content.read();
        if (read == -1) {
            break;
        }
        char c = (char) read;
        if (isTerminator(c, terminators)) {
            foundTerminator = true;
        } else {
            token.append(c);
        }
    }

    return token.toString();
}

private boolean isTerminator(char c, char[] terminators) {
    for (char terminator : terminators) {
        if (c == terminator) {
            return true;
        }
    }
    return false;
}

