        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

import java.util.List;

public class DoublyLinkedList<E> {
    private ListNode<E> head;
    private ListNode<E> tail;
    private int size;

    private static class ListNode<E> {
        E value;
        ListNode<E> prev;
        ListNode<E> next;

        ListNode(E value) {
            this.value = value;
            this.prev = null;
            this.next = null;
        }
    }

    public void moveAllListNodes(DoublyLinkedList<E> list) {
        if (list == null || list.isEmpty()) {
            return;
        }

        ListNode<E> current = list.head;
        while (current != null) {
            ListNode<E> next = current.next;
            list.removeListNode(current);
            addListNode(current);
            current = next;
        }
    }

    private void addListNode(ListNode<E> node) {
        if (head == null) {
            head = node;
            tail = node;
        } else {
            tail.next = node;
            node.prev = tail;
            tail = node;
        }
        size++;
    }

    private void removeListNode(ListNode<E> node) {
        if (node == head) {
            head = node.next;
        }
        if (node == tail) {
            tail = node.prev;
        }
        if (node.prev != null) {
            node.prev.next = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        }
        size--;
    }

    public int getSize() {
        return size;
    }

    public static void main(String[] args) {
        DoublyLinkedList<Integer> list1 = new DoublyLinkedList<>();
        list1.addListNode(new ListNode<>(1));
        list1.addListNode(new ListNode<>(2));
        list1.addListNode(new ListNode<>(3));

        DoublyLinkedList<Integer> list2 = new DoublyLinkedList<>();
        list2.addListNode(new ListNode<>(4));
        list2.addListNode(new ListNode<>(5));

        list1.moveAllListNodes(list2);

        System.out.println("List 1 size: " + list1.getSize()); // Output: 5
        System.out.println("List 2 size: " + list2.getSize()); // Output: 0
    }
}

public class StringUtils {
    /**
     * <p>Check if a String starts with a specified prefix (optionally case insensitive).</p>
     * @see String#startsWith(String)
     * @param str  the String to check, may be null
     * @param prefix the prefix to find, may be null
     * @param ignoreCase inidicates whether the compare should ignore case(case insensitive) or not.
     * @return <code>true</code> if the String starts with the prefix or both <code>null</code>
     */
    private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
        if (str == null || prefix == null) {
            return str == prefix;
        }
        if (ignoreCase) {
            return str.toLowerCase().startsWith(prefix.toLowerCase());
        } else {
            return str.startsWith(prefix);
        }
    }

    public static void main(String[] args) {
        System.out.println(startsWith("Hello", "He", true)); // true
        System.out.println(startsWith("Hello", "he", false)); // false
        System.out.println(startsWith("Hello", "World", true)); // false
        System.out.println(startsWith(null, "He", true)); // true
        System.out.println(startsWith("Hello", null, true)); // true
        System.out.println(startsWith(null, null, true)); // true
    }
}

