public class GraphUtils {

    /** 
     * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
     * @param graph the graph.
     * @param vertices the vertices to induce the subgraph from.
     * @return true if the induced subgraph is a clique.
     */
    private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
        for (V vertex : vertices) {
            for (V otherVertex : vertices) {
                if (vertex.equals(otherVertex)) {
                    continue;
                }
                if (!graph.containsEdge(vertex, otherVertex)) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Example usage
        Graph<String, String> graph = new SimpleGraph<>();
        graph.addEdge("A", "B");
        graph.addEdge("B", "C");
        graph.addEdge("C", "A");

        Set<String> vertices = Set.of("A", "B", "C");
        boolean result = isClique(graph, vertices);
        System.out.println("Is the subgraph a clique? " + result);
    }
}

