        File file = new File("path/to/thread/snapshots.txt");
        List<ProfileAnalyzeTimeRange> timeRanges = List.of(
            new ProfileAnalyzeTimeRange("2023-01-01", "2023-01-31"),
            new ProfileAnalyzeTimeRange("2023-02-01", "2023-02-28")
        );

        try {
            List<ThreadSnapshot> snapshots = parseFromFileWithTimeRange(file, timeRanges);
            System.out.println("Parsed Thread Snapshots: " + snapshots);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

class ProfileAnalyzeTimeRange {
    private String startDate;
    private String endDate;

    public ProfileAnalyzeTimeRange(String startDate, String endDate) {
        this.startDate = startDate;
        this.endDate = endDate;
    }

    // Getters and setters
    public String getStartDate() {
        return startDate;
    }

    public void setStartDate(String startDate) {
        this.startDate = startDate;
    }

    public String getEndDate() {
        return endDate;
    }

    public void setEndDate(String endDate) {
        this.endDate = endDate;
    }
}
